select coalesce(t.product_category_name_english,p.product_category_name,'unknown') c, sum(oi.price) gmv, sum(case when o.order_status not in ('canceled','unavailable') then oi.price end) gmv_ex
from order_items oi join orders o using(order_id) left join products p using(product_id) left join product_category_name_translation t using(product_category_name)
where year(o.order_purchase_timestamp)=2017 group by 1 order by 2 desc limit 7

select c.customer_state, sum(oi.price) gmv, sum(oi.price) filter (where o.order_status not in ('canceled','unavailable')) gmv_ex
from orders o join order_items oi using(order_id) join customers c using(customer_id)
where year(o.order_purchase_timestamp)=2018 group by 1 order by 2 desc limit 6

select o.order_status, sum(oi.price) p, sum(oi.freight_value) f, count(distinct o.order_id) n
from orders o join customers c using(customer_id) join order_items oi using(order_id)
where c.customer_state='MG' and year(o.order_purchase_timestamp)=2018 group by 1
